local SaffronGrower = {}
local PRODUCTS = {
    common_saffron_threads = { name = "Snop žafranovih niti", glassCost = 1, time = 4, cost = 60, food = 5, happiness = 1, prestige = 1, description = "Snop žafranovih niti za začimbno polje." },
    glass_jar_saffron = { name = "Kozarec žafrana", glassCost = 2, time = 6, cost = 160, food = 10, happiness = 2, prestige = 3, description = "Steklen kozarec žafrana za kuhinjo." },
    silver_box_saffron = { name = "Srebrna škatlica žafrana", glassCost = 2, silverCost = 1, time = 9, cost = 380, food = 18, prestige = 8, happiness = 3, description = "Srebrna škatlica z žafranom za plemiško mizo." },
    gold_lidded_saffron = { name = "Zlatopokrovka žafrana", glassCost = 2, goldCost = 1, silverCost = 1, time = 13, cost = 900, food = 30, prestige = 18, happiness = 5, description = "Žafran v škatli z zlatim pokrovom za visoke plemiče." },
    jewel_inlaid_saffron_casket = { name = "Draguljarska skrinjica žafrana", glassCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, time = 17, cost = 1900, food = 50, prestige = 30, happiness = 7, description = "Skrinjica z dragulji in žafranom za visoko plemstvo." },
    royal_saffron_treasury = { name = "Kraljevska zakladnica žafrana", glassCost = 5, goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 4200, food = 90, prestige = 60, happiness = 13, description = "Velika kraljevska zakladnica žafrana z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    saffron_field = { name = "Žafranovo polje", cost = { gold = 240, wood = 80, stone = 80 }, upkeep = 5, qualityBonus = 5 },
    drying_house = { name = "Sušilna hiša", cost = { gold = 900, wood = 240, stone = 280, glass = 6 }, upkeep = 22, qualityBonus = 18 },
    spice_atelier = { name = "Začimbni atelje", cost = { gold = 2400, wood = 360, stone = 520, silver = 30, glass = 14 }, upkeep = 55, qualityBonus = 30 },
    royal_saffron_palace = { name = "Kraljevska žafranova palača", cost = { gold = 9800, wood = 580, stone = 760, gold = 60, jewel = 16, glass = 30 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
SaffronGrower.glassStock = 14; SaffronGrower.silverStock = 8; SaffronGrower.goldStock = 6; SaffronGrower.jewelStock = 4; SaffronGrower.pearlStock = 4
SaffronGrower.productStock = {}; SaffronGrower.buildings = {}; SaffronGrower.maker = nil; SaffronGrower.activeMaking = {}; SaffronGrower.totalProducts = 0; SaffronGrower.dayTimer = 0
function SaffronGrower.init() SaffronGrower.glassStock=14; SaffronGrower.silverStock=8; SaffronGrower.goldStock=6; SaffronGrower.jewelStock=4; SaffronGrower.pearlStock=4; SaffronGrower.productStock={}; SaffronGrower.buildings={}; SaffronGrower.maker=nil; SaffronGrower.activeMaking={}; SaffronGrower.totalProducts=0; SaffronGrower.dayTimer=0; print("[SaffronGrower] Royal Saffron Grower System initialized (6 products, 4 buildings)") end
function SaffronGrower.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaffronGrower.maker={name=n or ("Žafranar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žafranar najet: %s (spretnost: %d)",SaffronGrower.maker.name,s),"success") end; return true end
function SaffronGrower.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaffronGrower.build(id) local ok,e=SaffronGrower.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaffronGrower.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaffronGrower.getQualityBonus() local b=0; for _,bd in ipairs(SaffronGrower.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaffronGrower.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and SaffronGrower.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and SaffronGrower.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SaffronGrower.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaffronGrower.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SaffronGrower.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SaffronGrower.buildings==0 then return false,"Potrebno žafranovo polje" end; if not SaffronGrower.maker then return false,"Potreben žafranar" end; return true end
function SaffronGrower.make(pt,qty) qty=qty or 1; local ok,e=SaffronGrower.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then SaffronGrower.glassStock=SaffronGrower.glassStock-d.glassCost*qty end; if d.silverCost then SaffronGrower.silverStock=SaffronGrower.silverStock-d.silverCost*qty end; if d.goldCost then SaffronGrower.goldStock=SaffronGrower.goldStock-d.goldCost*qty end; if d.jewelCost then SaffronGrower.jewelStock=SaffronGrower.jewelStock-d.jewelCost*qty end; if d.pearlCost then SaffronGrower.pearlStock=SaffronGrower.pearlStock-d.pearlCost*qty end; local t=d.time; if SaffronGrower.maker then t=math.max(1,t-math.floor(SaffronGrower.maker.skill/13)) end; table.insert(SaffronGrower.activeMaking,{id="saffron_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Setev: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaffronGrower.completeMaking(m) local q=1.0+(SaffronGrower.getQualityBonus()/100); if SaffronGrower.maker then q=q+(SaffronGrower.maker.skill/150) end; q=math.min(2.4,q); SaffronGrower.productStock[m.productType]=(SaffronGrower.productStock[m.productType] or 0)+m.quantity; SaffronGrower.totalProducts=SaffronGrower.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaffronGrower.maker then SaffronGrower.maker.itemsMade=SaffronGrower.maker.itemsMade+m.quantity; if math.random()<0.25 then SaffronGrower.maker.skill=math.min(100,SaffronGrower.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žafran pripravljen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"saffron.harvested",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function SaffronGrower.update(dt) if not _G.state then return end; SaffronGrower.dayTimer=SaffronGrower.dayTimer+dt; if SaffronGrower.dayTimer>=30 then SaffronGrower.dayTimer=0; for i=#SaffronGrower.activeMaking,1,-1 do local m=SaffronGrower.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaffronGrower.completeMaking(m); table.remove(SaffronGrower.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaffronGrower.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaffronGrower.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaffronGrower.getStats() return {glassStock=SaffronGrower.glassStock,silverStock=SaffronGrower.silverStock,goldStock=SaffronGrower.goldStock,jewelStock=SaffronGrower.jewelStock,pearlStock=SaffronGrower.pearlStock,productStock=SaffronGrower.productStock,numBuildings=#SaffronGrower.buildings,hasMaker=SaffronGrower.maker~=nil,makerName=SaffronGrower.maker and SaffronGrower.maker.name or "—",makerSkill=SaffronGrower.maker and SaffronGrower.maker.skill or 0,activeMaking=#SaffronGrower.activeMaking,totalProducts=SaffronGrower.totalProducts} end
return SaffronGrower
